// Helpers shared by the spec-gen area modules.

/** First line of every generated file, so readers and tools know not to edit it. */
export function header(source, comment = "//") {
	return `${comment} @generated by scripts/spec-gen.mjs from ${source} — do not edit; run \`pnpm spec:gen\`.\n`
}

/** A Rust string literal. JSON escapes are valid Rust escapes except `\u` forms, which spec text avoids. */
export function rustStr(s) {
	const json = JSON.stringify(s)
	if (/\\u/.test(json))
		throw new Error(`spec text needs a \\u escape, which rustStr does not convert: ${json}`)
	return json
}

/** `lower case` / `ad-hoc` / `camelCase` → `PascalCase`, for Rust enum variants. */
export function pascal(s) {
	return s
		.replace(/[^A-Za-z0-9]+(.)?/g, (_, c) => (c ? c.toUpperCase() : ""))
		.replace(/^./, (c) => c.toUpperCase())
}

/** `rust` → `&["a", "b"]` for a slice of string literals. */
export function rustStrSlice(items) {
	return `&[${items.map(rustStr).join(", ")}]`
}

/**
 * JSON for a TS literal: tab-indented, with any array or object that fits in
 * `width` columns on one line, so tables stay readable.
 */
export function tsJson(value, indent = "", width = 100) {
	const flat = JSON.stringify(value)
	if (flat === undefined || typeof value !== "object" || value === null) return flat
	if (indent.length * 4 + flat.length <= width)
		return flat.replace(/,(?=["[{\d tfn-])/g, ", ").replace(/":/g, '": ')
	const inner = `${indent}\t`
	if (Array.isArray(value)) {
		return `[\n${value.map((v) => inner + tsJson(v, inner, width)).join(",\n")},\n${indent}]`
	}
	const entries = Object.entries(value).map(
		([k, v]) => `${inner}${JSON.stringify(k)}: ${tsJson(v, inner, width)}`,
	)
	return `{\n${entries.join(",\n")},\n${indent}}`
}
